begin;
create table public.measurements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,contract_id uuid not null,competence date not null check(competence=date_trunc('month',competence)::date),status text not null default 'draft' check(status in('draft','closed','approved','cancelled')),notes text,closed_at timestamptz,closed_by uuid references auth.users(id),reopened_at timestamptz,reopened_by uuid references auth.users(id),reopen_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(tenant_id,company_id,contract_id) references public.engineering_contracts(tenant_id,company_id,id) on delete restrict,unique(tenant_id,company_id,contract_id,competence),unique(tenant_id,company_id,id));
create table public.measurement_lines(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,measurement_id uuid not null,contract_service_id uuid not null,structure_id uuid,measured_quantity numeric(18,6) not null check(measured_quantity>0),unit_price_snapshot numeric(18,6) not null check(unit_price_snapshot>=0),gross_value numeric(18,2) generated always as(round(measured_quantity*unit_price_snapshot,2)) stored,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(tenant_id,company_id,measurement_id) references public.measurements(tenant_id,company_id,id) on delete restrict,foreign key(tenant_id,company_id,contract_service_id) references public.contract_services(tenant_id,company_id,id) on delete restrict,unique(tenant_id,company_id,id));
create table public.measurement_reopen_log(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,measurement_id uuid not null,reason text not null,actor_user_id uuid references auth.users(id),created_at timestamptz not null default now(),foreign key(tenant_id,company_id,measurement_id) references public.measurements(tenant_id,company_id,id) on delete restrict);
create index measurements_contract_idx on public.measurements(tenant_id,company_id,contract_id,competence); create index measurement_lines_measurement_idx on public.measurement_lines(tenant_id,company_id,measurement_id); create index measurement_lines_service_idx on public.measurement_lines(tenant_id,company_id,contract_service_id); create index measurement_reopen_log_measurement_idx on public.measurement_reopen_log(tenant_id,company_id,measurement_id,created_at);
create or replace function public.validate_measurement_line() returns trigger language plpgsql set search_path='' as $$ declare v_contract uuid;v_work uuid;v_price numeric(18,6);v_qty numeric(18,6);v_prev numeric(18,6);v_status text;v_structure_work uuid; begin select m.contract_id,m.status into v_contract,v_status from public.measurements m where m.tenant_id=new.tenant_id and m.company_id=new.company_id and m.id=new.measurement_id; if not found then raise exception 'measurement not found'; end if; if v_status<>'draft' then raise exception 'only draft measurements can be edited'; end if; select cs.unit_price,cs.contracted_quantity,c.work_id into v_price,v_qty,v_work from public.contract_services cs join public.engineering_contracts c on c.tenant_id=cs.tenant_id and c.company_id=cs.company_id and c.id=cs.contract_id where cs.tenant_id=new.tenant_id and cs.company_id=new.company_id and cs.id=new.contract_service_id and cs.contract_id=v_contract for update of cs; if not found then raise exception 'contract service does not belong to measurement contract'; end if; if new.structure_id is not null then select ws.work_id into v_structure_work from public.work_structures ws where ws.tenant_id=new.tenant_id and ws.company_id=new.company_id and ws.id=new.structure_id; if not found or v_structure_work<>v_work then raise exception 'structure does not belong to contract work'; end if; end if; new.unit_price_snapshot:=v_price; select coalesce(sum(ml.measured_quantity),0) into v_prev from public.measurement_lines ml join public.measurements m on m.tenant_id=ml.tenant_id and m.company_id=ml.company_id and m.id=ml.measurement_id where ml.tenant_id=new.tenant_id and ml.company_id=new.company_id and ml.contract_service_id=new.contract_service_id and ml.id<>new.id and m.status in('draft','closed','approved'); if v_prev+new.measured_quantity>v_qty then raise exception 'measured quantity exceeds contracted quantity'; end if; return new; end $$;
revoke all on function public.validate_measurement_line() from public,anon,authenticated; create trigger measurement_lines_validate before insert or update on public.measurement_lines for each row execute function public.validate_measurement_line();
create or replace function public.guard_measurement_line_delete() returns trigger language plpgsql set search_path='' as $$ declare v_status text;begin select status into v_status from public.measurements where id=old.measurement_id;if v_status<>'draft' then raise exception 'closed/approved measurement lines are locked';end if;return old;end $$; revoke all on function public.guard_measurement_line_delete() from public,anon,authenticated; create trigger measurement_lines_delete_guard before delete on public.measurement_lines for each row execute function public.guard_measurement_line_delete();
create or replace function public.set_measurement_status(p_measurement_id uuid,p_action text,p_reason text default null) returns void language plpgsql security definer set search_path='' as $$ declare v public.measurements%rowtype; begin select * into v from public.measurements where id=p_measurement_id for update; if not found or not app_private.can_access_company(v.tenant_id,v.company_id) then raise exception 'measurement not found or inaccessible'; end if; if p_action='close' then if v.status<>'draft' then raise exception 'only draft can be closed';end if;update public.measurements set status='closed',closed_at=now(),closed_by=(select auth.uid()) where id=v.id; elsif p_action='approve' then if v.status<>'closed' then raise exception 'only closed can be approved';end if;update public.measurements set status='approved' where id=v.id; elsif p_action='reopen' then if v.status not in('closed','approved') then raise exception 'only closed/approved can be reopened';end if;if nullif(trim(p_reason),'') is null then raise exception 'reopen reason is required';end if;update public.measurements set status='draft',reopened_at=now(),reopened_by=(select auth.uid()),reopen_reason=p_reason where id=v.id;insert into public.measurement_reopen_log(tenant_id,company_id,measurement_id,reason,actor_user_id) values(v.tenant_id,v.company_id,v.id,p_reason,(select auth.uid())); else raise exception 'invalid measurement action';end if;end $$; revoke all on function public.set_measurement_status(uuid,text,text) from public,anon;grant execute on function public.set_measurement_status(uuid,text,text) to authenticated;
create view public.contract_service_measurement_balance with(security_invoker=true) as select cs.tenant_id,cs.company_id,cs.contract_id,cs.id contract_service_id,cs.contracted_quantity,coalesce(sum(ml.measured_quantity) filter(where m.status in('draft','closed','approved')),0) measured_quantity,cs.contracted_quantity-coalesce(sum(ml.measured_quantity) filter(where m.status in('draft','closed','approved')),0) remaining_quantity,cs.unit_price from public.contract_services cs left join public.measurement_lines ml on ml.tenant_id=cs.tenant_id and ml.company_id=cs.company_id and ml.contract_service_id=cs.id left join public.measurements m on m.tenant_id=ml.tenant_id and m.company_id=ml.company_id and m.id=ml.measurement_id group by cs.tenant_id,cs.company_id,cs.contract_id,cs.id,cs.contracted_quantity,cs.unit_price;
create trigger measurements_updated before update on public.measurements for each row execute function public.set_updated_at();create trigger measurement_lines_updated before update on public.measurement_lines for each row execute function public.set_updated_at();alter table public.measurements enable row level security;alter table public.measurement_lines enable row level security;alter table public.measurement_reopen_log enable row level security;
create policy measurements_select on public.measurements for select to authenticated using(app_private.can_access_company(tenant_id,company_id));create policy measurements_write on public.measurements for all to authenticated using(app_private.can_access_company(tenant_id,company_id)) with check(app_private.can_access_company(tenant_id,company_id));create policy measurement_lines_select on public.measurement_lines for select to authenticated using(app_private.can_access_company(tenant_id,company_id));create policy measurement_lines_write on public.measurement_lines for all to authenticated using(app_private.can_access_company(tenant_id,company_id)) with check(app_private.can_access_company(tenant_id,company_id));create policy measurement_reopen_log_select on public.measurement_reopen_log for select to authenticated using(app_private.can_access_company(tenant_id,company_id));commit;